import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function Home() {
  const navigate = useNavigate();  // useNavigate 사용
  const [currentDateTime, setCurrentDateTime] = useState('');

  // 현재 날짜와 시간을 반환하는 함수 (24시간 기준, 분까지만 표시)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    }); // 예: "2025년 1월 11일 금요일"
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    }); // 예: "15:05"

    return `${date} ${time}`; // 예: "2025년 1월 11일 금요일 15:05"
  };

  // 컴포넌트가 마운트될 때마다 시간을 갱신하도록 설정
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000); // 1초마다 시간을 갱신

    // 처음에 한 번 바로 시간을 갱신
    setCurrentDateTime(getCurrentDateTime());

    // 컴포넌트가 언마운트될 때 interval을 클리어
    return () => clearInterval(interval);
  }, []);

  return (
    <div>
      {/* 오늘 날짜와 시간 표시 */}
      <div>
        <strong>{currentDateTime}</strong>
      </div>
      <h1>Welcome to Chatbot</h1>
      <button onClick={() => navigate("/settings")}>시작하기</button>
    </div>
  );
}

export default Home;
